fn reverse_upto_k(s: &mut Vec<i32>, k: usize) {
    // Reverse the first k elements of the vector in place,
    // leaving the rest unchanged.
    //
    // It is assumed that 2 <= k <= s.len().
    //
    // We'll do an in-place swap from the ends of the prefix until meeting in the middle.

    let mut left = 0;
    let mut right = k - 1;

    while left < right {
        s.swap(left, right);
        left += 1;
        right -= 1;
    }
}